const D = { energy: .6, scale: 1, density: .5, weight: .6, hue: 28, speed: 1, x: .5, y: .52, alpha: 1, style: 'burin', act: 'plate', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const wt=cl(P.weight,0,1.6), sc=cl(P.scale,.5,2.2), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.2,4);
const en=cl(P.energy,0,1)*(.5+.6*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const cx=cl(P.x,.1,.9)*W, cy=cl(P.y,.1,.9)*Hh;

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
const kick=Math.min(1, K.pulse*.45 + S.bass*.55);

// ---- style: how form is BUILT, not just its hue ----
// NOTE (rescue): every ground here is TONED — mid-key. The first cut of this
// asset printed pale bistre onto near-ivory (paper b=92) and the whole plate
// washed out to an empty cream page at lum .78. Tone is the point of an
// engraving: it is built ENTIRELY from hatch density, so the paper must sit
// low enough for the ink to have somewhere to go.
const mezz=(sty==='mezzotint'), cont=(sty==='contour'), sang=(sty==='sanguine');
let pH,pS,pB, iH,iS,iB, xhatch=true, tonal=true;
if(mezz){ pH=252; pS=26; pB=7;  iH=md(H+18,360);  iS=6;  iB=95; tonal=true; }
else if(cont){ pH=208; pS=48; pB=14; iH=md(H+160,360); iS=30; iB=97; xhatch=false; tonal=false; }
else if(sang){ pH=34; pS=18; pB=66; iH=md(H-14,360); iS=66; iB=44; }
else { pH=42; pS=14; pB=58; iH=md(H+6,360); iS=36; iB=10; }

// ---- the plate: laid paper / mezzotint ground / burnished copper (cached) ----
const pkey=W+'x'+Hh+'|'+sty+'|'+P.seed;
if(!S.pl||S.plKey!==pkey){
  const g=(S.pl&&S.pl.width===W&&S.pl.height===Hh)?S.pl:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.noStroke(); g.background(pH,pS,pB);
  const up=(mezz||cont);
  g.strokeWeight(1);
  for(let i=0;i<Math.round(W/26);i++){ g.stroke(pH,pS+6,up?pB+7:pB-9,12); g.line(i*26+7,0,i*26+7,Hh); }
  for(let i=0;i<620;i++){ const x=fr(i*19)*W, y=fr(i*19+1)*Hh, a=fr(i*19+2)*TAU, L=2+fr(i*19+3)*13;
    g.stroke(pH,pS+9,up?pB+16:pB+13,8+fr(i*19+4)*14); g.line(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L); }
  g.noStroke();
  for(let i=0;i<760;i++){ const x=fr(i*37)*W, y=fr(i*37+1)*Hh;
    g.fill(pH,pS+10,up?pB+21:pB-16,6+fr(i*37+2)*11); g.circle(x,y,.7+fr(i*37+3)*2.3); }
  const m=u*0.045; g.noFill(); g.strokeWeight(Math.max(2,u*0.004));
  g.stroke(pH,pS+4,up?pB+18:pB-20,34); g.rect(m,m,W-2*m,Hh-2*m,u*0.006);
  g.strokeWeight(1); g.stroke(pH,pS+2,pB+22,26); g.rect(m+2,m+2,W-2*m-4,Hh-2*m-4,u*0.006);
  g.noStroke(); S.pl=g; S.plKey=pkey; }
image(S.pl,0,0);

// ---- THE SUBJECT: a modelled volume. A draped ovoid under a raking lamp. ----
// An ellipsoid height field + drapery folds that taper to nothing at the
// silhouette. Everything downstream reads tone off this — the engraving has a
// body to describe instead of an empty page.
const RX=.46*sc, RY=.52*sc, RZ=.40*sc;
const FOLD=.055*sc*(.45+en*.95);
const FW=7.4/sc;
const fd=T*.043+.8*Math.sin(T*.017)+.4*Math.sin(T*.0071);   // folds breathe, never repeat
const bf=2.1/sc, bg=1.7/sc, bt1=T*.037, bt2=T*.029;
const BAMP=.16;
let _gx=0,_gy=0,_in=0;
const field=(x,y)=>{
  const sa=Math.sin(x*bf+bt1), ca=Math.cos(x*bf+bt1), sb=Math.sin(y*bg-bt2), cb=Math.cos(y*bg-bt2);
  let h=BAMP*sa*cb, gx=BAMP*bf*ca*cb, gy=-BAMP*bg*sa*sb;
  let ins=0;
  const X=x/RX, Y=y/RY, rr=X*X+Y*Y;
  if(rr<1){
    ins=1;
    const q=Math.max(.09,Math.sqrt(1-rr));
    h+=RZ*q; gx+=RZ*(-X/RX)/q; gy+=RZ*(-Y/RY)/q;
    const tap=1-rr, sf=Math.sin(x*FW+fd), cf=Math.cos(x*FW+fd);
    h+=FOLD*tap*sf;
    gx+=FOLD*(tap*FW*cf - 2*X/RX*sf);
    gy+=FOLD*(-2*Y/RY*sf);
  }
  _gx=gx; _gy=gy; _in=ins; return h;
};

// ---- raking light on two incommensurate orbits (the primary motion floor) ----
let phi=T*.13+.75*Math.sin(T*.061)+1.1*Math.sin(T*.0237);
if(act==='proof') phi=T*.27+.9*Math.sin(T*.083);
const psi=.30+.20*Math.sin(T*.089)+.08*Math.sin(T*.0413);
const Lz=Math.sin(psi), Lc=Math.cos(psi), Lx=Math.cos(phi)*Lc, Ly=Math.sin(phi)*Lc;
const rel=(1.0+1.8*en)*(1+.28*kick*en);
const amb=mezz?.13:.19;
let inkTone=1; if(act==='burnish') inkTone=.6+.9*K.intensity;
// backdrop: a graded studio sweep, NOT lambert — a flat wall under a raking
// lamp would be uniformly black and swallow the whole frame.
const BD0=.60, BD1=.30;
const val=(px,py)=>{
  const x=(px-cx)/u, y=(py-cy)/u;
  field(x,y);
  if(_in){
    const gx=_gx*rel, gy=_gy*rel, nl=Math.sqrt(gx*gx+gy*gy+1);
    const v=(-gx*Lx-gy*Ly+Lz)/nl;
    return cl(amb+(1-amb)*cl(v,0,1),0,1);
  }
  const X=x/RX, Y=y/RY, rr=X*X+Y*Y;
  const roll=.10*Math.sin(x*bf+bt1)*Math.cos(y*bg-bt2);
  let vb=BD0+BD1*(.5-y)+roll;
  vb*=1-.40*Math.exp(-(rr-1)*2.6);          // occlusion halo hugging the form
  return cl(vb,0,1);
};

// ---- hatch: swelling burin ribbons that follow the surface contour ----
const a0=(sang?-.35:-.22)+.16*Math.sin(T*.023);
const fam=(ang,N,pitch,gamma,bend,wmul,shade)=>{
  const ca=Math.cos(ang), sa2=Math.sin(ang);
  const L=Math.abs(W*ca)+Math.abs(Hh*sa2)+u*.12;
  const NS=38, step=L/NS;
  const px=S._px||(S._px=new Float32Array(64)), py=S._py||(S._py=new Float32Array(64));
  const nxA=S._nx||(S._nx=new Float32Array(64)), nyA=S._ny||(S._ny=new Float32Array(64)), wA=S._w||(S._w=new Float32Array(64));
  for(let k=0;k<N;k++){
    const o=(k-(N-1)/2)*pitch + (fr(k*3+ang*17)-.5)*pitch*.34;
    let x=cx-ca*L/2-sa2*o, y=cy-sa2*L/2+ca*o;
    let dx=ca, dy=sa2, any=false;
    for(let s=0;s<=NS;s++){
      const v=val(x,y);
      let mark = shade? cl(v-.10,0,1) : cl(1-v,0,1);
      if(!tonal) mark=cl(.30+Math.min(Math.sqrt(_gx*_gx+_gy*_gy)*.30,.6),0,1);
      const w=pitch*wmul*Math.pow(mark,gamma)*wt*inkTone;
      px[s]=x; py[s]=y; nxA[s]=-dy; nyA[s]=dx; wA[s]=w; if(w>.30) any=true;
      const gl=Math.sqrt(_gx*_gx+_gy*_gy)+1e-5;
      let tx=-_gy/gl, ty=_gx/gl;
      if(tx*dx+ty*dy<0){ tx=-tx; ty=-ty; }
      const bnd=_in?bend:bend*.25;              // the backdrop hatch runs straight
      dx=dx*(1-bnd)+tx*bnd; dy=dy*(1-bnd)+ty*bnd;
      const dl=Math.sqrt(dx*dx+dy*dy)+1e-6; dx/=dl; dy/=dl;
      x+=dx*step; y+=dy*step;
    }
    if(!any) continue;
    beginShape();
    for(let s=0;s<=NS;s++) vertex(px[s]+nxA[s]*wA[s], py[s]+nyA[s]*wA[s]);
    for(let s=NS;s>=0;s--) vertex(px[s]-nxA[s]*wA[s], py[s]-nyA[s]*wA[s]);
    endShape(CLOSE);
  }
};

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
noStroke();
dc.globalCompositeOperation = mezz||cont ? 'lighter' : 'multiply';
const N1=Math.round(56+dens*48);
const ext1=Math.abs(W*Math.sin(a0))+Math.abs(Hh*Math.cos(a0))+u*.1;
fill(iH,iS,iB, (mezz?70:cont?64:92)*al);
fam(a0, N1, ext1/N1, sang?1.10:1.25, cont?.34:.52, .86, mezz);
if(xhatch){
  const a1=a0+(sang?1.02:1.18);
  const N2=Math.round(N1*(sang?.40:.60));
  const ext2=Math.abs(W*Math.sin(a1))+Math.abs(Hh*Math.cos(a1))+u*.1;
  fill(iH,iS,mezz?iB:iB+(sang?8:5), (mezz?52:sang?62:82)*al);
  fam(a1, N2, ext2/N2, mezz?2.4:2.15, .40, .62, mezz);
}

// ---- burin flicks in the deepest darks (the engraver's lozenge dots) ----
const NFL=Math.round(90+dens*140);
fill(iH,iS,mezz?100:iB+8,(mezz?60:74)*al);
for(let i=0;i<NFL;i++){
  const x=fr(i*41)*W, y=fr(i*41+1)*Hh, v=val(x,y);
  const m=mezz? cl(v-.35,0,1) : cl(.40-v,0,1);
  if(m<.03) continue;
  const a=fr(i*41+2)*TAU, len=u*.004*(1+m*4)*wt;
  push(); translate(x,y); rotate(a+_gx*.4); ellipse(0,0,len*2.4,len*.7+.7); pop();
}

// ---- ink tone: a slow wash that deepens the plate over the section arc ----
dc.globalCompositeOperation = mezz||cont ? 'source-over' : 'multiply';
if(!(mezz||cont)){ noStroke(); fill(iH,iS*.6,iB+30, (4+8*K.intensity)*al); rect(0,0,W,Hh); }
dc.globalCompositeOperation=oldOp;

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke(); noTint();
